set -e
CHK=$(mktemp -d /tmp/gatecheck.XXXXXX)
cat > "$CHK/check.mjs" <<'EOF'
import { execFile } from 'node:child_process';
import { mkdtemp } from 'node:fs/promises';
import os from 'node:os';
import path from 'node:path';
const BOT = process.argv[2];
const dir = await mkdtemp(path.join(os.tmpdir(), 'state-'));
process.env.STATE_DIR = dir;
const { reserve, release } = await import(BOT);
const H = 3600e3, M = 60e3;
const req = { userId: 'lead_204', maxPerWindow: 3, windowHours: 24, minGapMinutes: 90 };
const t0 = new Date('2026-10-22T10:00:00Z');
const ok = (c, msg) => { if (!c) { console.log('FAIL', msg); process.exitCode = 1; } else console.log('ok  ', msg); };

// gap
const a = await reserve(req, t0);
ok(a.allowed && a.reason === null && typeof a.reservationId === 'string', 'first send allowed');
const g = await reserve(req, new Date(t0.getTime() + 60 * M));
ok(!g.allowed && g.reason === 'min_gap_not_elapsed' && g.reservationId === null, 'gap refused at 60m');
// refusal must not spend a slot: retry after gap
const b = await reserve(req, new Date(t0.getTime() + 90 * M));
ok(b.allowed, 'allowed at exactly 90m gap');
const c = await reserve(req, new Date(t0.getTime() + 180 * M));
ok(c.allowed, 'third send allowed');
const d = await reserve(req, new Date(t0.getTime() + 270 * M));
ok(!d.allowed && d.reason === 'max_per_window_reached', 'fourth refused by window cap');

// release frees a slot, works and is idempotent
ok(await release(b.reservationId) === true, 'release returns true');
ok(await release(b.reservationId) === false, 'second release is no-op');
ok(await release('garbage') === false, 'bad id ignored');
const e = await reserve(req, new Date(t0.getTime() + 270 * M));
ok(e.allowed, 'slot reusable after release');

// sliding window: a send ages out at exactly windowHours
const t1 = new Date(t0.getTime() + 24 * H);
const f = await reserve(req, new Date(t0.getTime() + 24 * H + 1));
ok(f.allowed, 'after oldest send ages out a new one is allowed');

// other lead independent; per-call limits honoured
const other = await reserve({ ...req, userId: 'lead_999' }, t0);
ok(other.allowed, 'different lead not affected');
const tight = { userId: 'lead_555', maxPerWindow: 1, windowHours: 1, minGapMinutes: 0 };
ok((await reserve(tight, t0)).allowed, 'per-call maxPerWindow 1 first ok');
ok((await reserve(tight, new Date(t0.getTime() + M))).reason === 'max_per_window_reached', 'per-call cap respected');

// restart persistence: a fresh module instance sees the same history
const again = await import(BOT + '?fresh=' + Date.now());
ok((await again.reserve(tight, new Date(t0.getTime() + 2 * H))).allowed === true, 'fresh instance: window expired, allowed');

// concurrent processes: 12 workers race for the same lead, expect exactly maxPerWindow winners
const race = { userId: 'lead_race', maxPerWindow: 3, windowHours: 24, minGapMinutes: 0 };
const script = `
process.env.STATE_DIR=${JSON.stringify(dir)};
const { reserve } = await import(${JSON.stringify(BOT)});
const r = await reserve(${JSON.stringify(race)}, new Date('2026-10-22T12:00:00Z'));
console.log(JSON.stringify(r));`;
const runs = await Promise.all(Array.from({ length: 12 }, () =>
  new Promise((res, rej) => execFile(process.execPath, ['--input-type=module', '-e', script], (err, out) => err ? rej(err) : res(JSON.parse(out)))),
));
const wins = runs.filter(r => r.allowed).length;
ok(wins === 3, `12 concurrent processes -> ${wins} allowed (want 3)`);
ok(runs.filter(r => !r.allowed).every(r => r.reason === 'max_per_window_reached'), 'losers get window reason');

// release from a different process than the reserver
const winner = runs.find(r => r.allowed);
await new Promise((res, rej) => execFile(process.execPath, ['--input-type=module', '-e',
  `process.env.STATE_DIR=${JSON.stringify(dir)};const {release}=await import(${JSON.stringify(BOT)});console.log(await release(${JSON.stringify(winner.reservationId)}))`],
  (err, out) => err ? rej(err) : res(out)));
const after = await reserve(race, new Date('2026-10-22T12:00:01Z'));
ok(after.allowed, 'cross-process release frees a slot');
EOF
cd "$CHK" && node check.mjs <HOME>/Desktop/Open-Source/projelerim/proactive-gate/bench/head-to-head/results/round5-heldout-haiku/work/ours-g4-3/bot.mjs; echo "exit=$?"
